import React, { useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { createMoodEntry } from '../redux/slices/moodSlice';
import './MoodEntryForm.css';

const moodLabels = {
  1: 'Very Sad',
  2: 'Sad',
  3: 'Neutral',
  4: 'Happy',
  5: 'Very Happy'
};

const energyLabels = {
  1: 'Exhausted',
  2: 'Low Energy',
  3: 'Moderate',
  4: 'Energetic',
  5: 'Very Energetic'
};

const stressLabels = {
  1: 'None',
  2: 'Minimal',
  3: 'Moderate',
  4: 'High',
  5: 'Extreme'
};

const sleepLabels = {
  1: 'Poor',
  2: 'Fair',
  3: 'Average',
  4: 'Good',
  5: 'Excellent'
};

const MoodEntryForm = ({ onClose }) => {
  const dispatch = useDispatch();
  const { loading, error } = useSelector((state) => state.mood);
  
  const [formData, setFormData] = useState({
    mood_score: 3,
    energy_level: 3,
    stress_level: 3,
    sleep_quality: 3,
    notes: ''
  });
  
  const handleSliderChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: parseInt(value)
    });
  };
  
  const handleTextChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value
    });
  };
  
  const handleSubmit = async (e) => {
    e.preventDefault();
    
    const success = await dispatch(createMoodEntry(formData));
    if (success) {
      if (onClose) onClose();
    }
  };
  
  const getLabel = (type, value) => {
    switch (type) {
      case 'mood_score':
        return moodLabels[value];
      case 'energy_level':
        return energyLabels[value];
      case 'stress_level':
        return stressLabels[value];
      case 'sleep_quality':
        return sleepLabels[value];
      default:
        return '';
    }
  };
  
  return (
    <div className="mood-entry-form">
      <h2>How are you feeling today?</h2>
      
      {error && <div className="error-message">{error}</div>}
      
      <form onSubmit={handleSubmit}>
        <div className="form-group">
          <div className="slider-header">
            <label htmlFor="mood_score">Mood</label>
            <span className="slider-value">{getLabel('mood_score', formData.mood_score)}</span>
          </div>
          <input
            type="range"
            id="mood_score"
            name="mood_score"
            min="1"
            max="5"
            step="1"
            value={formData.mood_score}
            onChange={handleSliderChange}
          />
          <div className="slider-markers">
            <span>1</span>
            <span>2</span>
            <span>3</span>
            <span>4</span>
            <span>5</span>
          </div>
        </div>
        
        <div className="form-group">
          <div className="slider-header">
            <label htmlFor="energy_level">Energy</label>
            <span className="slider-value">{getLabel('energy_level', formData.energy_level)}</span>
          </div>
          <input
            type="range"
            id="energy_level"
            name="energy_level"
            min="1"
            max="5"
            step="1"
            value={formData.energy_level}
            onChange={handleSliderChange}
          />
          <div className="slider-markers">
            <span>1</span>
            <span>2</span>
            <span>3</span>
            <span>4</span>
            <span>5</span>
          </div>
        </div>
        
        <div className="form-group">
          <div className="slider-header">
            <label htmlFor="stress_level">Stress</label>
            <span className="slider-value">{getLabel('stress_level', formData.stress_level)}</span>
          </div>
          <input
            type="range"
            id="stress_level"
            name="stress_level"
            min="1"
            max="5"
            step="1"
            value={formData.stress_level}
            onChange={handleSliderChange}
          />
          <div className="slider-markers">
            <span>1</span>
            <span>2</span>
            <span>3</span>
            <span>4</span>
            <span>5</span>
          </div>
        </div>
        
        <div className="form-group">
          <div className="slider-header">
            <label htmlFor="sleep_quality">Sleep Quality</label>
            <span className="slider-value">{getLabel('sleep_quality', formData.sleep_quality)}</span>
          </div>
          <input
            type="range"
            id="sleep_quality"
            name="sleep_quality"
            min="1"
            max="5"
            step="1"
            value={formData.sleep_quality}
            onChange={handleSliderChange}
          />
          <div className="slider-markers">
            <span>1</span>
            <span>2</span>
            <span>3</span>
            <span>4</span>
            <span>5</span>
          </div>
        </div>
        
        <div className="form-group">
          <label htmlFor="notes">Notes (optional)</label>
          <textarea
            id="notes"
            name="notes"
            rows="4"
            value={formData.notes}
            onChange={handleTextChange}
            placeholder="How are you feeling? Any notable events today?"
          ></textarea>
        </div>
        
        <div className="form-actions">
          {onClose && (
            <button type="button" className="cancel-btn" onClick={onClose}>
              Cancel
            </button>
          )}
          <button type="submit" className="submit-btn" disabled={loading}>
            {loading ? 'Saving...' : 'Save Entry'}
          </button>
        </div>
      </form>
    </div>
  );
};

export default MoodEntryForm;
